import re

def entities(doc, scope):
    children = scope_nodes(doc, scope)
    objs_node = next((n for n in children if n.get("title", "").endswith(": Objects")), None)
    if not objs_node or objs_node.get("kind") != "list":
        return []
    res = []
    for line in objs_node.get("lines", []):
        m = re.match(r'Object (\d+): (.+?) \(color=', line)
        if m:
            res.append({"id": m.group(1), "description": m.group(2).strip()})
    return res

def recorded_end(doc, scope):
    children = scope_nodes(doc, scope)
    max_f = 0.0
    for n in children:
        title = n.get("title", "")
        if title.endswith(": Events"):
            for line in n.get("lines", []):
                m = re.match(r'Frame (\d+):', line)
                if m:
                    max_f = max(max_f, int(m.group(1)))
        elif title.endswith(": Motion log") and n.get("kind") == "table":
            for row in n.get("table", {}).get("rows", []):
                if row and row[0]:
                    try:
                        max_f = max(max_f, int(row[0]))
                    except ValueError:
                        pass
    return 127.0 if max_f == 0.0 else max_f

def inputs(doc, scope):
    children = scope_nodes(doc, scope)
    events_node = next((n for n in children if n.get("title", "").endswith(": Events")), None)
    if not events_node or events_node.get("kind") != "list":
        return []
    res = []
    for idx, line in enumerate(events_node.get("lines", [])):
        m = re.match(r'Frame (\d+): Object (\d+).*?(?: enters the scene\.| is in view when the video begins\.)', line)
        if m:
            frame = int(m.group(1))
            obj_id = m.group(2)
            res.append({
                "id": f"in_{frame}_{obj_id}",
                "time": float(frame),
                "kind": "enter",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], idx]]
            })
    return res

def outcomes(doc, scope):
    children = scope_nodes(doc, scope)
    events_node = next((n for n in children if n.get("title", "").endswith(": Events")), None)
    if not events_node or events_node.get("kind") != "list":
        return []
    res = []
    for idx, line in enumerate(events_node.get("lines", [])):
        m_collide = re.match(r'Frame (\d+): Object (\d+).*? collides with Object (\d+)', line)
        m_exit = re.match(r'Frame (\d+): Object (\d+).*? exits the scene\.', line)
        if m_collide:
            res.append({
                "time": float(m_collide.group(1)),
                "kind": "collide",
                "entities": [m_collide.group(2), m_collide.group(3)],
                "value": None,
                "src": [[events_node["node_id"], idx]]
            })
        elif m_exit:
            res.append({
                "time": float(m_exit.group(1)),
                "kind": "exit",
                "entities": [m_exit.group(2)],
                "value": None,
                "src": [[events_node["node_id"], idx]]
            })
    return res


