import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    scope_node = node_by_title(doc, scope)
    children_ids = scope_node.get("children", [])

    # Parse motion log
    motion_log = {}
    for cid in children_ids:
        child = node_by_id(doc, cid)
        if "Motion log" in child.get("title", "") and child.get("kind") == "table":
            for row in child.get("table", {}).get("rows", []):
                if not row or row[0] == "" or row[1] == "":
                    continue
                try:
                    frame = int(row[0])
                except (ValueError, IndexError):
                    continue
                obj_id = row[1].split()[0]
                try:
                    x, y, vx, vy = float(row[2]), float(row[3]), float(row[4]), float(row[5])
                except (ValueError, IndexError):
                    continue
                if obj_id not in motion_log:
                    motion_log[obj_id] = {}
                motion_log[obj_id][frame] = (x, y, vx, vy)

    # Parse objects info
    objects_info = {}
    for cid in children_ids:
        child = node_by_id(doc, cid)
        if "Objects" in child.get("title", "") and child.get("kind") == "list":
            for line in child.get("lines", []):
                m = re.match(r'Object (\d+):.*shape=(\w+)', line)
                if m:
                    objects_info[m.group(1)] = m.group(2)

    rec_end = recorded_end(doc, scope)
    sf = int(start) if start is not None else 0
    hf = int(horizon) if horizon is not None else int(rec_end)

    # Parse inputs
    enter_times = {}
    for evt in inputs:
        if evt["kind"] == "enter":
            for oid in evt["entities"]:
                enter_times[oid] = int(evt["time"])

    objs = sorted(enter_times.keys())

    # Physics parameters (calibrated from data)
    dt = 0.0285
    radii = {"sphere": 0.205, "cylinder": 0.215, "cube": 0.240}
    rest = 0.35

    def get_mu(shape, speed):
        if shape == "sphere":
            return 0.001 + 0.0012 * speed
        return 0.008

    def init_obj(oid, t):
        shape = objects_info.get(oid, "sphere")
        if oid not in motion_log:
            return None
        frames = sorted(motion_log[oid].keys())
        if not frames:
            return None
        # Find closest record at or before t, or just closest
        candidates = [f for f in frames if f <= t]
        if candidates:
            best = max(candidates)
        else:
            best = min(frames, key=lambda f: abs(f - t))
        x, y, vx, vy = motion_log[oid][best]
        # Step forward to t
        if best < t:
            for _ in range(best, int(t)):
                sp = math.sqrt(vx**2 + vy**2)
                if sp > 0.001:
                    m = get_mu(shape, sp)
                    x += vx * dt
                    y += vy * dt
                    vx *= math.exp(-m)
                    vy *= math.exp(-m)
        return {"x": x, "y": y, "vx": vx, "vy": vy, "shape": shape, "active": True}

    # Initialize state
    state = {}
    for oid in objs:
        ef = enter_times[oid]
        if ef <= sf:
            s = init_obj(oid, sf)
            if s:
                state[oid] = s
        else:
            shape = objects_info.get(oid, "sphere")
            state[oid] = {"entry": ef, "shape": shape, "active": False}

    # Run simulation
    outcomes = []
    recent = set()
    exited = set()

    for cf in range(sf, hf):
        # Activate objects entering at this frame
        for oid in objs:
            s = state.get(oid)
            if s and not s["active"] and s.get("entry") == cf:
                ns = init_obj(oid, cf)
                if ns:
                    state[oid] = ns

        # Step all active objects
        for oid in objs:
            s = state.get(oid)
            if not s or not s["active"]:
                continue
            sp = math.sqrt(s["vx"]**2 + s["vy"]**2)
            if sp < 0.001:
                s["vx"] = s["vy"] = 0.0
                continue
            m = get_mu(s["shape"], sp)
            s["x"] += s["vx"] * dt
            s["y"] += s["vy"] * dt
            s["vx"] *= math.exp(-m)
            s["vy"] *= math.exp(-m)

        # Check for exits
        for oid in objs:
            s = state.get(oid)
            if not s or not s["active"] or oid in exited:
                continue
            if abs(s["x"]) > 3.5 or abs(s["y"]) > 3.5:
                outcomes.append({
                    "time": float(cf),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": []
                })
                s["active"] = False
                exited.add(oid)

        # Check for collisions
        for i in range(len(objs)):
            for j in range(i + 1, len(objs)):
                o1, o2 = objs[i], objs[j]
                s1, s2 = state.get(o1), state.get(o2)
                if not s1 or not s2 or not s1["active"] or not s2["active"]:
                    continue
                key = tuple(sorted([o1, o2]))
                if key in recent:
                    continue
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                d = math.sqrt(dx * dx + dy * dy)
                r = radii.get(s1["shape"], 0.22) + radii.get(s2["shape"], 0.22)
                if d < r and d > 0.005:
                    nx, ny = dx / d, dy / d
                    vrn = (s1["vx"] - s2["vx"]) * nx + (s1["vy"] - s2["vy"]) * ny
                    if vrn < 0:
                        imp = -(1 + rest) * vrn / 2
                        s1["vx"] += imp * nx
                        s1["vy"] += imp * ny
                        s2["vx"] -= imp * nx
                        s2["vy"] -= imp * ny
                        # Separate objects
                        ov = r - d
                        if ov > 0:
                            s1["x"] -= ov / 2 * nx
                            s1["y"] -= ov / 2 * ny
                            s2["x"] += ov / 2 * nx
                            s2["y"] += ov / 2 * ny
                        recent.add(key)
                        outcomes.append({
                            "time": float(cf),
                            "kind": "collide",
                            "entities": sorted([o1, o2]),
                            "value": None,
                            "src": []
                        })

        # Reset recent for separated pairs
        nr = set()
        for k in recent:
            o1, o2 = k
            s1, s2 = state.get(o1), state.get(o2)
            if s1 and s2 and s1["active"] and s2["active"]:
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                d = math.sqrt(dx * dx + dy * dy)
                r = radii.get(s1["shape"], 0.22) + radii.get(s2["shape"], 0.22)
                if d <= r + 0.5:
                    nr.add(k)
        recent = nr

    return outcomes
